// models/User.js
import mongoose from 'mongoose';
import bcrypt from 'bcrypt';

const userSchema = new mongoose.Schema(
  {
    name: { type: String, required: [true, 'Name is required'], trim: true, minLength: 2 },
    email: { type: String, required: true, unique: true, lowercase: true, match: /^\S+@\S+\.\S+$/ },
    password: { type: String, required: true, minLength: 8, select: false },
    role: { type: String, enum: ['user', 'admin'], default: 'user' },
    age: { type: Number, min: 13, max: 120 },
  },
  { timestamps: true },
);

userSchema.virtual('initials').get(function () {
  return this.name.split(' ').map((p) => p[0]).join('').toUpperCase();
});

userSchema.pre('save', async function () {
  if (this.isModified('password')) this.password = await bcrypt.hash(this.password, 12);
});

userSchema.methods.checkPassword = function (plain) {
  return bcrypt.compare(plain, this.password);
};

userSchema.set('toJSON', { virtuals: true, transform: (_doc, ret) => { delete ret.__v; delete ret.password; return ret; } });

export default mongoose.models.User || mongoose.model('User', userSchema);

import express from 'express';
import User from './models/User.js';

const router = express.Router();

router.post('/', async (req, res, next) => {
  try {
    const user = await User.create(req.body);
    res.status(201).json(user);
  } catch (err) {
    next(err);
  }
});

router.get('/', async (req, res) => {
  const page = Math.max(1, Number(req.query.page) || 1);
  const limit = 20;
  const [items, total] = await Promise.all([
    User.find().sort('-createdAt').skip((page - 1) * limit).limit(limit).lean(),
    User.countDocuments(),
  ]);
  res.json({ items, total, page, pages: Math.ceil(total / limit) });
});

router.patch('/:id', async (req, res) => {
  const user = await User.findByIdAndUpdate(req.params.id, { $set: req.body }, { new: true, runValidators: true });
  if (!user) return res.status(404).json({ error: 'Not found' });
  res.json(user);
});

export const mongooseErrors = (err, req, res, next) => {
  if (err.name === 'ValidationError') return res.status(422).json({ errors: Object.fromEntries(Object.entries(err.errors).map(([k, v]) => [k, v.message])) });
  if (err.name === 'CastError') return res.status(400).json({ error: 'Invalid id' });
  if (err.code === 11000) return res.status(409).json({ error: 'Already exists', fields: Object.keys(err.keyPattern) });
  next(err);
};

