import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync(':memory:');      // or 'todos.db'
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE todos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    done INTEGER DEFAULT 0
  );
`);

const insert = db.prepare('INSERT INTO todos (title) VALUES (?)');
console.log(insert.run('learn node'));       // { changes: 1, lastInsertRowid: 1 }

db.exec('BEGIN');
try {
  for (const t of ['build api', 'deploy']) insert.run(t);
  db.exec('COMMIT');
} catch (err) {
  db.exec('ROLLBACK');
  throw err;
}

db.prepare('UPDATE todos SET done = 1 WHERE id = :id').run({ id: 1 });
console.log(db.prepare('SELECT * FROM todos WHERE done = ?').all(0));
// [ { id: 2, title: 'build api', done: 0 }, { id: 3, title: 'deploy', done: 0 } ]
console.log(db.prepare('SELECT count(*) AS n FROM todos').get());   // { n: 3 }
db.close();

import { createClient } from 'redis';

const redis = createClient({ url: process.env.REDIS_URL ?? 'redis://127.0.0.1:6379' });
redis.on('error', (err) => console.error('redis error', err));
await redis.connect();

export async function cached(key, ttlSeconds, loader) {
  const hit = await redis.get(key);
  if (hit) return JSON.parse(hit);                 // cache hit

  const value = await loader();                    // cache miss -> database
  await redis.set(key, JSON.stringify(value), { EX: ttlSeconds });
  return value;
}

